// These predecessor IDs recognize durable transcript ownership only. They do not
// participate in live package discovery, service selection, or tool dispatch.
private static bool HasExpectedHistoricalOwner(string? recordedPackageId, string expectedPackageId)
    => string.Equals(
        recordedPackageId switch
        {
            "sunder.package.agent.tools.files" => "younics.ai.agent.tools.files",
            "sunder.package.agent.tools.shell" => "younics.ai.agent.tools.shell",
            "sunder.package.agent.tools.web" => "younics.ai.agent.tools.web",
            "sunder.package.agent.subagents" => "younics.ai.agent.subagents",
            "sunder.package.agent.skills" => "younics.ai.agent.skills",
            _ => recordedPackageId,
        },
        expectedPackageId,
        StringComparison.Ordinal);
